INSERT OR IGNORE INTO characters(slug,name,house,affiliation,summary,source_id) VALUES
('harry-potter','Harry Potter','Gryffindor','Dumbledore''s Army; Hogwarts','Penyihir yang tumbuh tanpa mengetahui dunia sihir, kemudian belajar di Hogwarts dan menjadi pusat konflik melawan Voldemort.',2001),
('hermione-granger','Hermione Granger','Gryffindor','Dumbledore''s Army; Hogwarts','Murid kelahiran Muggle yang dikenal sangat tekun belajar, kuat dalam pemecahan masalah, dan berperan penting dalam perjalanan Harry dan Ron.',2002),
('ron-weasley','Ron Weasley','Gryffindor','Dumbledore''s Army; keluarga Weasley','Sahabat Harry dan Hermione yang menonjol melalui loyalitas, keberanian, humor, serta kemampuan bermain catur sihir dan Quidditch.',2003),
('minerva-mcgonagall','Minerva McGonagall','Gryffindor','Hogwarts staff; Order of the Phoenix','Profesor Transfigurasi yang tegas dan adil, Animagus, serta tokoh penting dalam kepemimpinan dan pertahanan Hogwarts.',2004),
('severus-snape','Severus Snape','Slytherin','Hogwarts staff; Order of the Phoenix','Penyihir dengan kemampuan kuat pada ramuan, Occlumency, Legilimency, dan duel; perannya terhubung dengan beberapa kelompok yang saling berlawanan.',2005),
('sirius-black','Sirius Black','Gryffindor','Order of the Phoenix; Marauders','Anggota keluarga Black yang menolak nilai keluarganya, sahabat James Potter, dan kemudian menjadi figur keluarga penting bagi Harry.',2006),
('rubeus-hagrid','Rubeus Hagrid','Gryffindor','Hogwarts staff; Order of the Phoenix','Penjaga tanah dan pengajar Pemeliharaan Satwa Gaib yang memiliki kedekatan khusus dengan banyak makhluk sihir.',2007),
('draco-malfoy','Draco Malfoy','Slytherin','Hogwarts; keluarga Malfoy','Murid Slytherin yang menjadi rival Harry; tekanan keluarga dan konflik yang membesar menguji pilihan serta kesetiaannya.',2008),
('lord-voldemort','Lord Voldemort / Tom Riddle','Slytherin','Death Eaters','Penyihir gelap yang mengejar kekuasaan dan keabadian melalui sihir hitam, menjadi pusat dua perang sihir besar.',2009),
('remus-lupin','Remus Lupin','Gryffindor','Order of the Phoenix; Marauders; Hogwarts staff','Mantan Marauder dan pengajar Pertahanan terhadap Ilmu Hitam yang membimbing Harry memahami Patronus.',2010),
('arthur-weasley','Arthur Weasley','Gryffindor','Ministry of Magic; keluarga Weasley','Pegawai Kementerian dan ayah keluarga Weasley yang sangat tertarik pada benda serta kehidupan Muggle.',2003),
('albus-dumbledore','Albus Dumbledore','Gryffindor','Hogwarts; Order of the Phoenix','Kepala sekolah Hogwarts pada sebagian besar masa sekolah Harry dan salah satu penyihir paling berpengaruh dalam konflik melawan Voldemort.',2011);

INSERT OR IGNORE INTO creatures(slug,name,classification,habitat,danger_level,summary,source_id) VALUES
('dementor','Dementor','Non-being','Azkaban','Sangat tinggi','Makhluk berjubah yang menguras kebahagiaan dan menimbulkan keputusasaan; Patronus menjadi pertahanan utama terhadap mereka.',2020),
('basilisk','Basilisk','XXXXX','Chamber of Secrets','Ekstrem','Ular raksasa beracun dengan tatapan mematikan dan hubungan khusus dengan Parseltongue.',2021),
('hippogriff','Hippogriff','XXX','Eropa; Forbidden Forest','Sedang','Makhluk setengah elang setengah kuda yang menuntut penghormatan ketika didekati dan mampu terbang membawa penunggang.',2022),
('phoenix','Phoenix','XXXX','Daerah pegunungan; dapat dipelihara secara langka','Rendah','Burung sihir langka yang dapat lahir kembali dari abu dan memiliki kemampuan penyembuhan melalui air mata.',2023),
('house-elf','House-elf','Being','Rumah keluarga penyihir; Hogwarts','Bervariasi','Makhluk dengan sihir kuat yang dalam banyak konteks terikat pada keluarga atau tempat yang dilayaninya.',2024),
('acromantula','Acromantula','XXXXX','Hutan; koloni besar','Ekstrem','Laba-laba raksasa berbisa yang mampu berbicara dan berbahaya bagi manusia yang memasuki wilayahnya.',2025),
('boggart','Boggart','Non-being','Ruang gelap dan tertutup','Psikologis','Makhluk yang mengambil rupa ketakutan terbesar orang yang menghadapinya; Riddikulus digunakan untuk mengubah situasi menjadi bahan tawa.',2036);

INSERT OR IGNORE INTO spells(slug,name,incantation,type,purpose,difficulty,legal_status,source_id) VALUES
('alohomora','Unlocking Charm','Alohomora','Charm','Membuka banyak kunci dasar, kecuali yang dilindungi sihir penangkal tertentu.','Dasar','Umum',2030),
('expelliarmus','Disarming Charm','Expelliarmus','Charm','Melucuti tongkat dari lawan dan sering digunakan dalam duel tanpa tujuan melukai.','Menengah','Umum',2031),
('expecto-patronum','Patronus Charm','Expecto Patronum','Charm','Menghasilkan pelindung sihir terhadap Dementor dan dapat digunakan untuk mengirim pesan.','Lanjut','Umum',2032),
('accio','Summoning Charm','Accio','Charm','Memanggil objek menuju pengguna sihir.','Menengah','Umum',2033),
('lumos','Wand-lighting Charm','Lumos','Charm','Menghasilkan cahaya pada ujung tongkat.','Dasar','Umum',2034),
('wingardium-leviosa','Levitation Charm','Wingardium Leviosa','Charm','Membuat objek melayang.','Dasar','Umum',2035),
('riddikulus','Boggart-Banishing Charm','Riddikulus','Spell','Mengubah penampilan Boggart menjadi bentuk yang memancing tawa dan membantu mengusirnya.','Menengah','Umum',2036);

INSERT OR IGNORE INTO locations(slug,name,region,summary,source_id) VALUES
('hogwarts','Hogwarts','Scottish Highlands','Sekolah sihir dalam sebuah kastil besar dengan aula, perpustakaan, dungeon, menara, lorong rahasia, dan banyak ruang lain.',2011),
('diagon-alley','Diagon Alley','London','Kawasan perbelanjaan utama komunitas sihir Inggris, tersembunyi dari dunia Muggle dan berisi berbagai toko serta Gringotts.',2012),
('hogsmeade','Hogsmeade','Scottish Highlands','Permukiman sihir dekat Hogwarts yang dapat dikunjungi murid tertentu dan memiliki toko, pub, serta jalur rahasia menuju sekolah.',2013),
('ministry-of-magic','Ministry of Magic','London','Pusat pemerintahan komunitas sihir Inggris dengan berbagai departemen termasuk penegakan hukum dan misteri.',2014),
('azkaban','Azkaban','North Sea','Penjara terpencil yang lama dijaga Dementor dan menampung penyihir berbahaya.',2015),
('gringotts','Gringotts','Diagon Alley','Bank sihir yang dioperasikan goblin dengan jaringan ruang bawah tanah dan perlindungan kuat.',2016);

INSERT OR IGNORE INTO glossary(term,slug,definition,aliases,source_id) VALUES
('Animagus','animagus','Penyihir yang dapat berubah menjadi hewan tertentu melalui kemampuan sihir khusus.','[]',2004),
('Azkaban','azkaban','Penjara untuk penyihir dan penyihir gelap berbahaya yang terletak di Laut Utara.','[]',2015),
('Dementor','dementor','Makhluk non-being yang menguras kebahagiaan dan dapat melakukan Dementor''s Kiss.','[]',2020),
('Hogwarts','hogwarts','Sekolah sihir yang berada di dataran tinggi Skotlandia dalam sebuah kastil besar.','[]',2011),
('Hogsmeade','hogsmeade','Permukiman sihir di dekat Hogwarts.','[]',2013),
('Patronus','patronus','Manifestasi perlindungan sihir yang dapat mengambil bentuk hewan dan digunakan menghadapi Dementor.','["Patronus Charm"]',2032),
('Parseltongue','parseltongue','Kemampuan langka untuk berbicara dengan ular.','[]',2021),
('Quidditch','quidditch','Olahraga sihir beregu yang dimainkan di udara dengan sapu dan beberapa jenis bola.','[]',NULL),
('Wizengamot','wizengamot','Lembaga yudisial dan dewan penting dalam pemerintahan sihir Inggris.','[]',2014),
('Occlumency','occlumency','Seni melindungi pikiran dari pembacaan atau penetrasi melalui Legilimency.','[]',2005),
('Legilimency','legilimency','Kemampuan sihir untuk menembus dan membaca pikiran atau ingatan orang lain.','[]',2005),
('Horcrux','horcrux','Objek atau wadah yang terkait dengan upaya sihir gelap memecah dan menyimpan bagian jiwa.','[]',2009);

INSERT OR IGNORE INTO events(slug,title,year,year_label,era,summary,location_id,source_id) VALUES
('hogwarts-founded','Pendirian Hogwarts',NULL,'sekitar abad ke-10','Awal sejarah sekolah','Hogwarts didirikan oleh empat penyihir dan penyihir perempuan yang kemudian diasosiasikan dengan empat asrama.',(SELECT id FROM locations WHERE slug='hogwarts'),2011),
('chamber-opened','Pembukaan Chamber of Secrets',NULL,'tahun kedua Harry','Masa sekolah Harry','Serangkaian serangan membuat penghuni Hogwarts membatu dan mengungkap rahasia lama di bawah kastil.',(SELECT id FROM locations WHERE slug='hogwarts'),2011),
('triwizard-tournament','Triwizard Tournament di Hogwarts',NULL,'tahun keempat Harry','Masa sekolah Harry','Hogwarts menjadi tuan rumah Turnamen Triwizard yang mempertemukan tiga sekolah sihir.',(SELECT id FROM locations WHERE slug='hogwarts'),2011),
('harry-hearing','Sidang Harry di Kementerian',NULL,'sebelum tahun kelima Harry','Masa sekolah Harry','Harry menghadapi pemeriksaan resmi terkait penggunaan sihir di bawah umur dalam konteks serangan Dementor.',(SELECT id FROM locations WHERE slug='ministry-of-magic'),2014),
('ministry-battle','Pertempuran di Kementerian',NULL,'akhir tahun kelima Harry','Perang Sihir Kedua','Dumbledore''s Army, Order of the Phoenix, dan Death Eaters berhadapan di Departemen Misteri.',(SELECT id FROM locations WHERE slug='ministry-of-magic'),2014),
('sirius-escape','Sirius Black melarikan diri dari Azkaban',NULL,'sebelum tahun ketiga Harry','Masa sekolah Harry','Sirius menjadi salah satu tahanan terkenal yang berhasil keluar dari Azkaban.',(SELECT id FROM locations WHERE slug='azkaban'),2015),
('gringotts-breakin','Penyusupan ke Gringotts',NULL,'Perang Sihir Kedua','Perang Sihir Kedua','Harry, Ron, dan Hermione memasuki Gringotts dalam pencarian Horcrux.',(SELECT id FROM locations WHERE slug='gringotts'),2016),
('battle-of-hogwarts','Pertempuran Hogwarts',NULL,'akhir Perang Sihir Kedua','Perang Sihir Kedua','Hogwarts menjadi lokasi pertempuran besar yang menentukan akhir konflik utama melawan Voldemort.',(SELECT id FROM locations WHERE slug='hogwarts'),2011);

INSERT OR IGNORE INTO daily_features(feature_date,feature_type,entity_type,entity_id,headline,note) VALUES
('2026-09-14','creature','creature',(SELECT id FROM creatures WHERE slug='hippogriff'),'Makhluk Hari Ini','Pendekatan terhadap Hippogriff menekankan penghormatan sebelum kedekatan.'),
('2026-09-14','spell','spell',(SELECT id FROM spells WHERE slug='alohomora'),'Mantra Hari Ini','Alohomora adalah contoh charm dasar dengan batasan karena kunci dapat diberi perlindungan tambahan.'),
('2026-09-14','fact','location',(SELECT id FROM locations WHERE slug='hogwarts'),'Fakta Hari Ini','Hogwarts memiliki banyak jalur, ruang, dan rahasia sehingga peta aplikasi dibuat sebagai navigasi editorial, bukan denah resmi.');
